#!/bin/bash\n\necho \"🎬 Studio AI - Quick Start\"\necho \"=========================\"\necho \"\"\n\n# Check if Docker is installed\nif ! command -v docker &> /dev/null; then\n    echo \"❌ Docker not found. Please install Docker first:\"\n    echo \"   Visit: https://www.docker.com/products/docker-desktop\"\n    exit 1\nfi\n\necho \"✅ Docker found\"\necho \"\"\n\n# Check if Docker Compose is installed\nif ! command -v docker-compose &> /dev/null; then\n    echo \"⚠️  Docker Compose not found. Installing...\"\n    sudo apt update\n    sudo apt install -y docker-compose\nfi\n\necho \"✅ Docker Compose ready\"\necho \"\"\n\n# Create necessary directories\necho \"📁 Creating directories...\"\nmkdir -p outputs uploads models logs\necho \"✅ Directories created\"\necho \"\"\n\n# Build images\necho \"🔨 Building Docker images...\"\ndocker-compose build\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Build failed\"\n    exit 1\nfi\n\necho \"✅ Build complete\"\necho \"\"\n\n# Start services\necho \"🚀 Starting Studio AI...\"\ndocker-compose up -d\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Start failed\"\n    exit 1\nfi\n\necho \"✅ Studio AI started\"\necho \"\"\n\n# Wait for services to be ready\necho \"⏳ Waiting for services to start...\"\nsleep 10\n\n# Check if services are running\necho \"✅ Services running:\"\ndocker-compose ps\n\necho \"\"\necho \"================================================================\"\necho \"✅ Studio AI is ready!\"\necho \"================================================================\"\necho \"\"\necho \"🌐 Access the app:\"\necho \"   Frontend: http://localhost:3000\"\necho \"   Backend:  http://localhost:5000\"\necho \"   Redis:    localhost:6379\"\necho \"\"\necho \"📖 Documentation:\"\necho \"   Installation: see docs/INSTALLATION.md\"\necho \"   API: see docs/API.md\"\necho \"   Settings: see docs/SETTINGS.md\"\necho \"\"\necho \"🐳 Docker commands:\"\necho \"   View logs: docker-compose logs -f\"\necho \"   Stop: docker-compose down\"\necho \"   Restart: docker-compose restart\"\necho \"\"\necho \"🎉 Happy creating!\"\necho \"================================================================\"\n"
